&#34;&gt;&#39;volume&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;showColor&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;palette&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;original_color&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;136&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;     style&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;plot&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;style_columns&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; transp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;showColor&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;35&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;137&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;138&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// plot volume trend SMA&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;139&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;p1 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;plot&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;bullish_sma&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; title&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Bullish Volume Trend&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;140&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;     linewidth&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;green&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; transp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;141&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;p2 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;plot&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;bearish_sma&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; title&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Bearish Volume Trend&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;142&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;     linewidth&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;red&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;   transp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;143&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;144&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// fill area between volume trend&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;145&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;fill&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;p1&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; p2&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;bullish_sma&lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt;bearish_sma&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;green&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;red&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; transp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;75&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;146&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;147&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// add bgcolor to highlight large volume&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;148&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;is_large_volume &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; volume &lt;span class=&#34;token operator&#34;&gt;&gt;&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;2.25&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;ema&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;volume&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;149&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;bgcolor&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;is_large_volume&lt;span class=&#34;token operator&#34;&gt;?&lt;/span&gt;palette&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;na&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; transp&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;90&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; title&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;Highlight large volume&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h1 id=&#34;typescript-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#typescript-learning&#34;&gt;#&lt;/a&gt; Typescript Learning&lt;/h1&gt;
&lt;h3 id=&#34;在-vscode-终端中无法直接-npm-ls-g-很有可能是权限不够-以管理员身份启动-vscode-解决&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#在-vscode-终端中无法直接-npm-ls-g-很有可能是权限不够-以管理员身份启动-vscode-解决&#34;&gt;#&lt;/a&gt; 在 VSCODE 终端中无法直接 npm ls -g 很有可能是权限不够 以管理员身份启动 VSCODE 解决&lt;/h3&gt;
&lt;h3 id=&#34;npm-常用命令&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#npm-常用命令&#34;&gt;#&lt;/a&gt; npm 常用命令&lt;/h3&gt;
&lt;pre&gt;&lt;code&gt;npm ls -g
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这样只会查到包 不会查到依赖&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;npm ls -g --depth 0
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;只显示生产环境依赖的包&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;npm ls --depth 0 --prod
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;只显示开发环境依赖的包&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;npm ls --depth 0 --dev
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;我们安装完成 &lt;a href=&#34;https://so.csdn.net/so/search?q=node&amp;amp;spm=1001.2101.3001.7020&#34;&gt;node&lt;/a&gt; 环境后，默认使用的 &lt;a href=&#34;https://so.csdn.net/so/search?q=%E9%95%9C%E5%83%8F%E6%BA%90&amp;amp;spm=1001.2101.3001.7020&#34;&gt;镜像源&lt;/a&gt; 是 npm，但是有时候，需要切换到其他的镜像源安装依赖，这时候我们需要用 nrm（npm registry manager ）进行源的快速切换。&lt;/p&gt;
&lt;h1 id=&#34;node-使用-nrm-切换镜像源-更快安装依赖&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#node-使用-nrm-切换镜像源-更快安装依赖&#34;&gt;#&lt;/a&gt; node 使用 nrm 切换镜像源 - 更快安装依赖&lt;/h1&gt;
&lt;h2 id=&#34;1安装-nrm&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#1安装-nrm&#34;&gt;#&lt;/a&gt; 1. 安装 &lt;a href=&#34;https://so.csdn.net/so/search?q=nrm&amp;amp;spm=1001.2101.3001.7020&#34;&gt;nrm&lt;/a&gt;&lt;/h2&gt;
&lt;p&gt;安装 nrm 很简单，使用  &lt;code&gt;npm install -g nrm&lt;/code&gt;  可以直接就全局安装 ()&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/NdEhmTPa5vI3lYf.png&#34; alt=&#34;&#34; /&gt;&lt;br /&gt;
 安装完成后，我们可以使用  &lt;code&gt;nrm ls&lt;/code&gt;  查看所有的可用源，展示的源前有 * 的表示目前正在使用的源。&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/lwBn5fXo9MgNdqc.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;2切换源&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#2切换源&#34;&gt;#&lt;/a&gt; 2. 切换源&lt;/h2&gt;
&lt;p&gt;我们通过  &lt;code&gt;nrm ls&lt;/code&gt;  查看目前可用的源后，需要切换到某个源，直接使用  &lt;code&gt;nrm use &amp;lt;源名&amp;gt;&lt;/code&gt;  即可完成切换。比如我们需要切换到 taobao 的源直接使用  &lt;code&gt;nrm use taobao&lt;/code&gt; &lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/iDqWpIURM9n2AuC.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;3增加源&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#3增加源&#34;&gt;#&lt;/a&gt; 3. 增加源&lt;/h2&gt;
&lt;p&gt;有时我们需要增加一些定制的源，如公司内部自己的私有源，我们使用  &lt;code&gt;nrm add &amp;lt;源名&amp;gt; &amp;lt;源 url&amp;gt;&lt;/code&gt;   进行添加。&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/uvs76ydPr1eiQEW.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;4删除源&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#4删除源&#34;&gt;#&lt;/a&gt; 4. 删除源&lt;/h2&gt;
&lt;p&gt;删除不需要的源使用  &lt;code&gt;nrm del &amp;lt;源名&amp;gt;&lt;/code&gt;  进行删除&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/zs9ZYStfHnk1OWG.png&#34; alt=&#34;&#34; /&gt;&lt;br /&gt;
我们也可以使用  &lt;code&gt;nrm test &amp;lt;源名&amp;gt;&lt;/code&gt;  去测试速度，以方便我们选择使用哪个源&lt;/p&gt;
&lt;h3 id=&#34;因为在此系统上禁止运行脚本解决办法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#因为在此系统上禁止运行脚本解决办法&#34;&gt;#&lt;/a&gt; “因为在此系统上禁止运行脚本” 解决办法&lt;/h3&gt;
&lt;p&gt;&lt;a href=&#34;https://zhuanlan.zhihu.com/p/493496089&#34;&gt;原地址&lt;/a&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;figcaption data-lang=&#34;text&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;set-ExecutionPolicy RemoteSigned&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;改回去&lt;/p&gt;
&lt;figure class=&#34;highlight text&#34;&gt;&lt;figcaption data-lang=&#34;text&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;set-ExecutionPolicy Default&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/kyMZD9n5pUo8Bcx.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h3 id=&#34;安装-typescript-并检测-tsc短端口类型脚本编译器&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装-typescript-并检测-tsc短端口类型脚本编译器&#34;&gt;#&lt;/a&gt; 安装 typescript 并检测 tsc（短端口类型脚本编译器）&lt;/h3&gt;
&lt;pre&gt;&lt;code&gt;npm i -g typescript
&lt;/code&gt;&lt;/pre&gt;
&lt;pre&gt;&lt;code&gt;tsc -v
&lt;/code&gt;&lt;/pre&gt;
&lt;h3 id=&#34;常用-terminal-命令&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#常用-terminal-命令&#34;&gt;#&lt;/a&gt; 常用 terminal 命令&lt;/h3&gt;
&lt;pre&gt;&lt;code&gt;cd ~
&lt;/code&gt;&lt;/pre&gt;
&lt;pre&gt;&lt;code class=&#34;language-Sh&#34;&gt;mkdir #新文件夹名字
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/6JmfTwYqzDoNr1R.png&#34; alt=&#34;&#34; /&gt;&lt;br /&gt;
&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/wH9lBKIvO4nWixh.png&#34; alt=&#34;&#34; /&gt;&lt;br /&gt;
在 vscode 中打开现在的目录文件夹&lt;/p&gt;
&lt;figure class=&#34;highlight sh&#34;&gt;&lt;figcaption data-lang=&#34;sh&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;code &lt;span class=&#34;token builtin class-name&#34;&gt;.&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;&lt;img loading=&#34;lazy&#34; data-src=&#34;https://s2.loli.net/2024/08/09/6HzlByNfnPmwj8X.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h2 id=&#34;linux-创建新文件的命令&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#linux-创建新文件的命令&#34;&gt;#&lt;/a&gt; linux 创建新文件的命令&lt;/h2&gt;
&lt;ol&gt;
&lt;li&gt;vi 或 vim&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;[root@localhost ~]# vi file1.txt// 直接创建并打开一个文件 file1.txt&lt;/p&gt;
&lt;p&gt;用 vi 编辑器编辑文本后，如果是新创建的文件，默认保存在当前目录下，如果想保存到指定目录下，可以在 vi 编辑器中，按 Esc 键切换到命令模式，然后用 w 命令写到指定目录下的指定新建文件，如写到 /tmp/test.txt 文件，则在 vi 命令模式下输入: w /tmp/test.txt 写好后，在 /tmp 目录下新的文件 test.txt 就被创建了。&lt;/p&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;touch&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;[root@localhost ~]# touch file2.txt// 创建新的空文件 file2.txt&lt;/p&gt;
&lt;p&gt;touch 的另一个作用是更改一个文件或目录的时间。&lt;/p&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;echo&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;[root@localhost ~]# echo &amp;quot;this is a new file&amp;quot; &amp;gt; file3.txt// 创建文件 file3.txt 并将 this is a new file 写入&lt;/p&gt;
&lt;p&gt;(说明：使用&amp;gt; 指令覆盖文件原内容并重新输入内容，若文件不存在则创建文件。)&lt;/p&gt;
&lt;p&gt;[root@localhost ~]# echo &amp;quot;add contents&amp;quot; &amp;gt;&amp;gt;file3.txt// 在已存在的文件补充写入新内容 add contents&lt;/p&gt;
&lt;p&gt;(说明：使用&amp;gt;&amp;gt; 指令向文件追加内容，原内容将保存。)&lt;/p&gt;
&lt;p&gt;拓展： Linux 中输出重定向 &amp;gt; 和 &amp;gt;&amp;gt; 的区别，&amp;gt; 是覆盖，&amp;gt;&amp;gt; 是追加&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;会重写文件，如果文件里面有内容会覆盖。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;blockquote&gt;
&lt;blockquote&gt;
&lt;p&gt;追加文件。也就是如果文件里面有内容会把新内容追加到文件尾&lt;/p&gt;
&lt;/blockquote&gt;
&lt;/blockquote&gt;
&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;less 、more 、cat&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;三者都是将文件内容输出到标准输出，其中 less 和 more 可以分页显示，cat 是显示全部。&lt;/p&gt;
&lt;p&gt;三者可以根据已经存在的文件创建新的文件。假设已经存在文件 1.txt。&lt;/p&gt;
&lt;p&gt;cat 1.txt &amp;gt; 2.txt&lt;/p&gt;
&lt;p&gt;less 1.txt &amp;gt; 3.txt&lt;/p&gt;
&lt;p&gt;more 1.txt &amp;gt; 4.txt&lt;/p&gt;
&lt;p&gt;此时创建的文件内容都和 1.txt 中文件内容相同。&lt;/p&gt;
&lt;p&gt;cat 命令可以一次显示整个文件，如果文件比较大，使用不是很方便；适用于文件内容少的情况。&lt;/p&gt;
&lt;p&gt;cat 主要有三大功能：&lt;/p&gt;
&lt;p&gt;1) 一次显示整个文件: cat filename&lt;/p&gt;
&lt;p&gt;2) 从键盘创建一个文件: cat &amp;gt; filename 只能创建新文件，不能编辑已有文件.&lt;/p&gt;
&lt;p&gt;3) 将几个文件合并为一个文件: cat file1 file2 &amp;gt; file&lt;/p&gt;
&lt;p&gt;more 命令可以让屏幕在显示满一屏幕时暂停，此时可按空格健继续显示下一个画面，或按 Q 键停止显示。&lt;/p&gt;
&lt;p&gt;less 命令也可以分页显示文件，和 more 命令的区别就在于它支持上下键卷动屏幕，当结束浏览时，只要在 less 命令的提示符 “:” 下按 Q 键即可。&lt;/p&gt;
&lt;ol start=&#34;5&#34;&gt;
&lt;li&gt;cd&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;[root@localhost ~]# cd &amp;gt; file3.txt// 创建新的空文件 file3.txt&lt;/p&gt;
&lt;p&gt;[root@localhost ~]# cd &amp;gt;&amp;gt; file4.txt// 创建新的空文件 file3.txt&lt;/p&gt;
&lt;p&gt;cd 最主要的作用是切换目录，在 cd 后面跟 &amp;gt; 或 &amp;gt;&amp;gt; 再加上文件名就可以创建一个内容为空的文件。它和 echo 的区别之处在于 echo 可写文件内容，而 cd 并不能。&lt;br /&gt;
————————————————&lt;br /&gt;
