on&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;location&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;bottom&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;51&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;plotshape&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;Sell&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;white&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; style&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;shape&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;triangledown&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; text&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;Sell&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; location&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;location&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;bottom&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;p&gt;&lt;div class=&#34;links&#34;&gt;&lt;div class=&#34;item&#34; title=&#34;Microsoft&#34; style=&#34;--block-color:#0e4775;&#34;&gt;&lt;a href=&#34;https://msrc.microsoft.com/update-guide/&#34; class=&#34;image&#34; data-background-image=&#34;https://s2.loli.net/2024/08/16/sgVvmW1RXSiaxe2.png&#34;&gt;&lt;/a&gt;
        &lt;div class=&#34;info&#34;&gt;
        &lt;a href=&#34;https://msrc.microsoft.com/update-guide/&#34; class=&#34;title&#34;&gt;Security Update Guide&lt;/a&gt;
        &lt;p class=&#34;desc&#34;&gt;Microsoft Security Update Guide&lt;/p&gt;
        &lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The six actively zero-day vulnerabilities：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;CVE-2024-38178 - Scripting Engine Memory Corruption Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38193 - Windows Ancillary Function Driver for WinSock Elevation of Privilege Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38213 - Windows Mark of the Web Security Feature Bypass Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38106 - Windows Kernel Elevation of Privilege Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38107 - Windows Power Dependency Coordinator Elevation of Privilege Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38189 - Microsoft Project Remote Code Execution Vulnerability&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;The four publicly disclosed vulnerabilities：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;CVE-2024-38199 - Windows Line Printer Daemon (LPD) Service Remote Code Execution Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-21302 - Windows Secure Kernel Mode Elevation of Privilege Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38200 - Microsoft Office Spoofing Vulnerability&lt;/li&gt;
&lt;li&gt;CVE-2024-38202 - Windows Update Stack Elevation of Privilege Vulnerability&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;The 89 vulnerabilities：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;36 Elevation of Privilege Vulnerabilities&lt;/li&gt;
&lt;li&gt;4 Security Feature Bypass Vulnerabilities&lt;/li&gt;
&lt;li&gt;28 Remote Code Execution Vulnerabilities&lt;/li&gt;
&lt;li&gt;8 Information Disclosure Vulnerabilities&lt;/li&gt;
&lt;li&gt;6 Denial of Service Vulnerabilities&lt;/li&gt;
&lt;li&gt;7 Spoofing Vulnerabilities&lt;/li&gt;
&lt;/ul&gt;
